from copy import deepcopy
from prepare_audit import OUT,read,save,sha

TRIAL=OUT/'process_relation_trial_011'
EXTENSION='process_saved_polyguanamine_workup_recovery'


def build(r,a):
 f=r['fragments'];v=lambda group,key:f[group]['captures'][key]['value_raw'];label=r['product_target']['original_sample']['sample_label_raw'];imp=v('separation','impurity_label')
 def par(role,g,k,unit=None):return dict(role=role,value_raw=v(g,k),unit_raw=v(g,unit) if unit else None,source_fragment=g,source_capture=k)
 def reagent(role,g,name,mass,amount):
  return dict(role=role,value_raw=v(g,name),mass_raw=v(g,mass),mass_unit_raw=v(g,mass+'_unit'),amount_raw=v(g,amount),amount_unit_raw=v(g,amount+'_unit'),source_fragment=g,source_captures=[name,mass,mass+'_unit',amount,amount+'_unit'])
 states=[dict(id='REPORTED_CHARGE_INPUTS',kind='state',sample=label,state='DMSO reaction medium during guanamine addition in the reported presence of sodium hydride',premixing_sequence_of_base_not_asserted=True,base_dissolution_or_homogeneity_not_asserted=True),dict(id='AFTER_1C',kind='state',sample=label,state='stirred reported guanamine/DMSO/NaH preparation'),dict(id='AFTER_DROPWISE_ADDITION',kind='state',sample=label,state='reaction mixture after the reported dropwise addition at its addition temperature'),dict(id='AFTER_RT_REACTION',kind='state',sample=label,state='polycondensation mixture after the subsequent room-temperature stirring'),dict(id='CRUDE_PRECIPITATE',kind='state',sample=label,state='precipitate in excess methanol before filtration'),dict(id='FILTERED_CRUDE',kind='state',sample=label,state='crude precipitate collected by filtration'),dict(id='WASHED_CRUDE',kind='state',sample=label,state='methanol-washed crude polymer before THF separation',existing_state_target=r['old_wash_state_target']),dict(id='THF_SYSTEM',kind='state',sample=label,state='dissolved product in THF with a small amount of insoluble '+imp),dict(id='THF_FILTRATE',kind='state',sample=label,state='retained THF-soluble polymer filtrate after removal of '+imp),dict(id='INSOLUBLE_SIDE_STREAM',kind='state',sample=imp,state='THF-insoluble compound filtered off',cyclic_structure_not_recovered=True),dict(id='REPRECIPITATED_POLYMER',kind='state',sample=label,state='polyguanamine reprecipitated from retained THF filtrate into methanol'),dict(id='VACUUM_DRIED_POLYMER',kind='state',sample=label,state='isolated polyguanamine after vacuum drying',total_crude_yield_not_assigned_to_purified_polymer=True)]
 def op(i,name,ins,outs,parameters):return dict(id=i,kind='operation',sample=label,name=name,inputs=ins,outputs=outs,parameters=parameters,scope='this source-named typical preparation only')
 ops=[op('ADD_GUANAMINE',v('charge','charge_action')+' guanamine with '+v('charge','mixing'),['REPORTED_CHARGE_INPUTS'],['AFTER_1C'],[reagent('guanamine reagent','charge','monomer_label','monomer_mass','monomer_amount'),par('DMSO solvent volume','charge','first_solvent_volume','first_solvent_volume_unit'),reagent('base','charge','base','base_mass','base_amount')]),
  op('ADD_DIBROMOALKANE',v('charge','addition'),['AFTER_1C'],['AFTER_DROPWISE_ADDITION'],[reagent('dibromoalkane reagent','charge','second_monomer','second_monomer_mass','second_monomer_amount'),par('DMA solution volume','charge','second_solvent_volume','second_solvent_volume_unit'),par('addition temperature','charge','addition_temperature','addition_temperature_unit')]),
  op('STIR_RT',v('charge','reaction_action'),['AFTER_DROPWISE_ADDITION'],['AFTER_RT_REACTION'],[par('reaction temperature','charge','reaction_temperature'),par('reaction duration','charge','reaction_duration','reaction_duration_unit')]),
  op('PRECIPITATE_CRUDE',v('charge','precipitation_action')+' reaction mixture into precipitant',['AFTER_RT_REACTION'],['CRUDE_PRECIPITATE'],[par('precipitant','charge','first_precipitant')]),
  op('FILTER_CRUDE',v('old_wash_state','first_collection'),['CRUDE_PRECIPITATE'],['FILTERED_CRUDE'],[]),
  op('WASH_CRUDE',v('old_wash_state','washing'),['FILTERED_CRUDE'],['WASHED_CRUDE'],[par('wash liquid','old_wash_state','wash_liquid')]),
  op('DISSOLVE_THF',v('separation','dissolution'),['WASHED_CRUDE'],['THF_SYSTEM'],[par('solvent','separation','dissolution_solvent')]),
  op('REMOVE_INSOLUBLE',v('separation','impurity_collection'),['THF_SYSTEM'],['THF_FILTRATE','INSOLUBLE_SIDE_STREAM'],[par('separated insoluble compound mass','separation','impurity_mass','impurity_mass_unit'),par('reported separated compound yield','separation','impurity_yield','impurity_yield_unit')]),
  op('REPRECIPITATE_FILTRATE',v('separation','reprecipitation')+' retained '+v('separation','retained_stream'),['THF_FILTRATE'],['REPRECIPITATED_POLYMER'],[par('reprecipitant','separation','reprecipitant')]),
  op('DRY_POLYMER',v('drying','drying'),['REPRECIPITATED_POLYMER'],['VACUUM_DRIED_POLYMER'],[par('drying environment','drying','drying_environment'),par('isolated purified product mass','drying','product_mass','product_mass_unit'),par('isolated purified product yield','drying','product_yield','product_yield_unit')])]
 orders=[dict(id='SEQUENCE_'+str(i),kind='order',before=b['id'],after=c['id'],relation='precedes',basis='same source-confirmed typical procedure with explicit conjunctions and material-stream continuity, not JSON array order') for i,(b,c) in enumerate(zip(ops,ops[1:]))]
 bindings=[dict(id='SCOPE_'+o['id'],kind='binding',sample=label,operation_id=o['id'],input_states=o['inputs'],output_states=o['outputs'],side_output_sample=imp if o['id']=='REMOVE_INSOLUBLE' else None) for o in ops]
 bindings += [dict(id='POLYMER_IDENTITY',kind='binding',sample=label,output_state='VACUUM_DRIED_POLYMER',existing_sample_targets=[r['product_target']],relation='same named material identity, not a new physical batch transfer'),dict(id='OLD_WASH_STATE_IDENTITY',kind='binding',sample=label,output_state='WASHED_CRUDE',existing_sample_targets=[r['old_wash_state_target']],relation='source-confirmed typical-procedure scope of the existing washed-crude state'),dict(id='INSOLUBLE_SIDE_IDENTITY',kind='binding',sample=imp,output_state='INSOLUBLE_SIDE_STREAM',existing_sample_targets=[r['impurity_target']],relation='separated insoluble compound, not methanol-reprecipitated polymer')]
 return dict(proposal_id=r['proposal_id'],product_label=label,impurity_label=imp,operations=ops,parameters=[],states=states,orders=orders,bindings=bindings,saved_fragments=f,source_approval_path=a['path'],source_approval_sha256=a['sha256'],other_polymer_recipe_and_catalytic_use_not_recovered=True,total_crude_yield_not_recovered=True,new_pdf_information_extracted=0)


def main():
 pp=OUT/'process_relation_trial_010/freeze.json';parent=read(pp);approved={x['reference_no']:x for x in read(OUT/'saved_polyguanamine_workup_recovery/source_reviews/manifest.json')['papers']};rows=[];repairs=[]
 for p in parent['papers']:
  assert sha(p['candidate_path'])==p['candidate_sha256'];row=deepcopy(p);row['changed_from_immediate_parent']=False
  if p['reference_no'] in approved:
   a=approved[p['reference_no']];assert sha(a['path'])==a['sha256'];ap=read(a['path']);assert sha(ap['proposal_path'])==ap['proposal_sha256'];packet=read(ap['proposal_path']);r=packet['proposals'][0];old=read(p['candidate_path']);new=deepcopy(old);new[EXTENSION]=[build(r,a)];ns=r['product_target']['path'].split('/')[1];matches=[(i,s) for i,s in enumerate(new[ns]['process_steps']) if s['process_type']=='reprecipitation' and r['product_target']['sample_id'] in s['output_sample_ids'] and r['impurity_target']['sample_id'] in s['output_sample_ids']];assert len(matches)==1;i,s=matches[0];before=deepcopy(s['output_sample_ids']);s['output_sample_ids']=[r['product_target']['sample_id']];repairs.append(dict(reference_no=p['reference_no'],path=f'/{ns}/process_steps/{i}/output_sample_ids',before=before,after=s['output_sample_ids'],source_approval_path=a['path'],source_approval_sha256=a['sha256'],reason='THF-soluble retained-polymer reprecipitation belongs to this named typical procedure; insoluble compound is a filtered side stream, other synthetic batches are not products of this physical procedure'))
   dest=TRIAL/'papers'/(p['reference_no']+'.json');save(dest,new);row.update(candidate_path=str(dest),candidate_sha256=sha(dest),changed_from_parent=True,changed_from_immediate_parent=True,immediate_parent_candidate_path=p['candidate_path'],immediate_parent_candidate_sha256=p['candidate_sha256'])
  rows.append(row)
 save(TRIAL/'process_scope_repairs.json',dict(repairs=repairs,original_property_fields_modified=False,reference_values_used_as_prediction_inputs=False))
 save(TRIAL/'freeze.json',dict(version='process_relation_trial_011',parent_trial='process_relation_trial_010',parent_trial_freeze_sha256=sha(pp),baseline_candidate='candidate_v10',baseline_candidate_freeze_sha256=sha(OUT/'candidate_v10/freeze.json'),prediction_application_code_sha256=sha(__file__),proposal_generation_code_sha256=sha(OUT/'propose_saved_polyguanamine_workup.py'),scope_repairs_sha256=sha(TRIAL/'process_scope_repairs.json'),papers=rows,papers_total=101,cumulative_changed_papers=sum(bool(p.get('changed_from_parent')) for p in rows),changed_papers_this_round=1,property_content_or_bindings_modified=False,frozen_original_outputs_modified=False,existing_candidate_process_fields_revised=len(repairs),reference_answers_or_scores_used_as_prediction_inputs=False,reference_seen_previously_during_error_diagnosis=True,new_pdf_information_extracted=0,stable_workflow_release=False,external_api_calls=0));print({'papers':101,'changed_this_round':1,'scope_fields_repaired':len(repairs),'cumulative_changed_papers':sum(bool(p.get('changed_from_parent')) for p in rows)})

